// TEMA 14 — Delitos contra el patrimonio y el orden socioeconómico (Título XIII del Libro II CP).
// Hurtos, robos, extorsión, robo y hurto de uso de vehículos, daños, disposiciones comunes y ampliación del temario
// (usurpación, estafas, administración desleal, apropiación indebida, defraudaciones de fluido, propiedad intelectual e industrial).
// Formato: o[0] es SIEMPRE la respuesta correcta (la web baraja el orden al mostrarla).
// Verificado contra: Código Penal, BOE-A-1995-25444, texto consolidado (última actualización publicada el 09/04/2026,
// que incluye la LO 1/2026, de 8 de abril, de multirreincidencia, en vigor el 10/04/2026).
window.BANCO = window.BANCO || {};
window.BANCO[14] = [
  // --- ESTRUCTURA Y REFORMA ---
  {id:"T14-001", p:"¿En qué Título del Libro II del Código Penal se regulan los delitos contra el patrimonio y el orden socioeconómico?", o:["Título XIII","Título XII","Título XIV","Título XVII"], e:"Están en el Título XIII del Libro II. El Título XVII es el de los delitos contra la seguridad colectiva.", a:"Título XIII del Libro II CP (arts. 234 y ss.)", f:"Texto legal"},
  {id:"T14-002", p:"¿Cómo se denomina el Capítulo IV del Título XIII del Código Penal?", o:["Del robo y hurto de uso de vehículos","De la extorsión","De la usurpación","De las defraudaciones"], e:"Capítulos: I hurtos; II robos; III extorsión; IV robo y hurto de uso de vehículos; V usurpación; VI defraudaciones…", a:"Título XIII, Capítulo IV CP (art. 244)", f:"Texto legal"},
  {id:"T14-003", p:"¿En qué capítulo del Título XIII se regulan los daños?", o:["Capítulo IX","Capítulo VI","Capítulo X","Capítulo V"], e:"Los daños son el Capítulo IX (arts. 263 a 267). El Capítulo X contiene las disposiciones comunes (arts. 268 y 269).", a:"Título XIII, Capítulo IX CP", f:"Texto legal"},
  {id:"T14-004", p:"¿Cuál de las siguientes NO es una sección del Capítulo VI («De las defraudaciones») del Título XIII?", o:["De la receptación","De las estafas","De la apropiación indebida","De las defraudaciones de fluido eléctrico y análogas"], e:"Secciones del Capítulo VI: 1.ª estafas; 2.ª administración desleal; 2.ª bis apropiación indebida; 3.ª defraudaciones de fluido eléctrico y análogas. La receptación está en el Capítulo XIV.", a:"Título XIII, Capítulo VI CP", f:"Texto legal"},
  {id:"T14-005", p:"¿Qué ley orgánica, en vigor desde el 10 de abril de 2026, modificó los artículos 234, 235, 248, 250 y 255 del Código Penal?", o:["La LO 1/2026, de 8 de abril, en materia de multirreincidencia","La LO 14/2022, de 22 de diciembre","La LO 10/2022, de 6 de septiembre","La LO 1/2015, de 30 de marzo"], e:"La LO 1/2026, de 8 de abril, de multirreincidencia (BOE de 9/04/2026, en vigor el 10/04/2026), modificó, entre otros, los arts. 22, 66, 80, 234, 235, 248, 250, 255 y 568 CP. Ojo: tu temario la fecha en un punto el «8 de mayo», que es una errata.", a:"LO 1/2026 (arts. 234, 235, 248, 250 y 255 CP)", f:"Texto legal (BOE-A-2026-7966)"},

  // --- HURTO (ARTS. 234-236) ---
  {id:"T14-006", p:"Según el artículo 234.1 CP, ¿qué pena corresponde al hurto cuando la cuantía de lo sustraído excede de 400 euros?", o:["Prisión de seis a dieciocho meses","Prisión de uno a tres años","Multa de uno a tres meses","Prisión de tres a seis meses o multa de seis a doce meses"], e:"Art. 234.1: «…con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros».", a:"Art. 234.1 CP", f:"Texto legal"},
  {id:"T14-007", p:"¿Cuáles son los elementos del delito de hurto del artículo 234.1 CP?", o:["Tomar, con ánimo de lucro, cosas muebles ajenas sin la voluntad de su dueño","Apoderarse de cosas muebles ajenas con fuerza en las cosas","Obligar a otro con violencia a realizar un acto en perjuicio de su patrimonio","Apropiarse de una cosa mueble recibida en depósito"], e:"Art. 234.1: «El que, con ánimo de lucro, tomare las cosas muebles ajenas sin la voluntad de su dueño…». Sin fuerza, violencia ni intimidación.", a:"Art. 234.1 CP", f:"Texto legal"},
  {id:"T14-008", p:"Según el artículo 234.2 CP, si lo sustraído no excede de 400 euros (y no concurren circunstancias del 235), la pena es:", o:["Multa de uno a tres meses","Multa de tres a doce meses","Prisión de seis a dieciocho meses","Localización permanente de dos a doce días"], e:"Art. 234.2: «Se impondrá la pena de multa de uno a tres meses si la cuantía de lo sustraído no excediese de 400 euros, salvo si concurriese alguna de las circunstancias del artículo 235».", a:"Art. 234.2 CP", f:"Texto legal"},
  {id:"T14-009", p:"Según el artículo 234.2 CP, aunque lo sustraído no exceda de 400 euros, se impondrá la pena del apartado 1 (prisión de seis a dieciocho meses) cuando el culpable:", o:["Haya sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza comprendidos en el Título XIII, siendo al menos uno de ellos leve","Haya sido condenado por cualquier delito en los últimos cinco años","Tenga dos antecedentes por hurto, aunque estén cancelados","Actúe de noche"], e:"Art. 234.2: «…en el caso de que el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza, comprendidos en este Título, y siendo al menos uno de ellos leve, se impondrá la pena prevista en el apartado 1». No se tienen en cuenta los antecedentes cancelados o que debieran serlo.", a:"Art. 234.2, párrafo segundo, CP", f:"Texto legal"},
  {id:"T14-010", p:"Según el artículo 234.3 CP, las penas del hurto se impondrán en su mitad superior cuando:", o:["Se hayan neutralizado, eliminado o inutilizado los dispositivos de alarma o seguridad instalados en las cosas sustraídas","Se cometa de noche","Se sustraigan objetos de un vehículo","Lo sustraído supere los 1.000 euros"], e:"Art. 234.3: mitad superior cuando se hubieran neutralizado, eliminado o inutilizado, por cualquier medio, los dispositivos de alarma o seguridad instalados en las cosas sustraídas.", a:"Art. 234.3 CP", f:"Texto legal"},
  {id:"T14-011", p:"Una persona arranca en una tienda la alarma antirrobo de una prenda de 80 euros y sale sin pagar. ¿Cómo se castiga, si no concurre ninguna circunstancia del artículo 235?", o:["Como hurto del art. 234.2 (multa de uno a tres meses) impuesta en su mitad superior (art. 234.3)","Como robo con fuerza en las cosas del art. 240","Como hurto del art. 234.1 (prisión de seis a dieciocho meses)","Como delito de daños"], e:"Inutilizar el dispositivo de seguridad de la propia cosa no convierte el hurto en robo, porque la fuerza no se usa para acceder al lugar. Con 80 euros es hurto leve (234.2) y el 234.3 obliga a imponer la pena en su mitad superior.", a:"Art. 234.2 y 3 CP", f:"Texto legal"},
  {id:"T14-012", p:"Según el artículo 235.1 CP, el hurto agravado se castiga con:", o:["Prisión de uno a tres años","Prisión de seis a dieciocho meses","Prisión de dos a cinco años","Prisión de uno a cinco años"], e:"Art. 235.1: «El hurto será castigado con la pena de prisión de uno a tres años» cuando concurra alguna de sus circunstancias.", a:"Art. 235.1 CP", f:"Texto legal"},
  {id:"T14-013", p:"¿Qué circunstancia agravante del hurto añadió la LO 1/2026 como numeral 10.º del artículo 235.1 CP?", o:["Que los objetos sustraídos sean teléfonos móviles u otros dispositivos móviles de comunicación o de almacenamiento de información digital","Que el hurto se cometa en transporte público","Que la víctima sea mayor de 65 años","Que el autor actúe encapuchado"], e:"Art. 235.1.10.º (LO 1/2026): teléfonos móviles y otros dispositivos móviles de comunicación o almacenamiento masivo de información digital que puedan contener datos personales. No se incluyen los que estén a la venta, en almacén o en exposición en establecimientos comerciales.", a:"Art. 235.1.10.º CP", f:"Texto legal"},
  {id:"T14-014", p:"El hurto de un teléfono móvil expuesto a la venta en una tienda, ¿se agrava por el artículo 235.1.10.º CP?", o:["No, porque se excluyen los dispositivos que estén a la venta, en almacén o en exposición en establecimientos comerciales","Sí, siempre que se trate de un teléfono móvil","Sí, si su valor supera los 400 euros","Sí, si el autor es reincidente"], e:"Art. 235.1.10.º: «A los efectos de este numeral, no se considerarán incluidos los que se encuentren a la venta, almacén o exposición en establecimientos comerciales».", a:"Art. 235.1.10.º CP", f:"Texto legal"},
  {id:"T14-015", p:"Según el artículo 235.1.7.º CP, se agrava el hurto cuando al delinquir el culpable haya sido condenado ejecutoriamente por:", o:["Al menos tres delitos menos graves o graves del Título XIII, siempre que sean de la misma naturaleza","Al menos dos delitos de cualquier naturaleza","Al menos tres delitos leves de hurto","Un delito grave de robo"], e:"Art. 235.1.7.º: al menos tres delitos menos graves o graves comprendidos en este título, de la misma naturaleza. No se tienen en cuenta los antecedentes cancelados o que debieran serlo.", a:"Art. 235.1.7.º CP", f:"Texto legal"},
  {id:"T14-016", p:"Según el artículo 235.1.8.º CP, ¿cuándo se agrava el hurto por la intervención de menores?", o:["Cuando se utilice a menores de dieciséis años para cometer el delito","Cuando el autor sea menor de edad","Cuando la víctima sea menor de dieciocho años","Cuando se utilice a menores de catorce años"], e:"Art. 235.1.8.º: «Cuando se utilice a menores de dieciséis años para la comisión del delito».", a:"Art. 235.1.8.º CP", f:"Texto legal"},
  {id:"T14-017", p:"Según el artículo 235.1.4.º CP, el hurto de productos agrarios o ganaderos se agrava cuando:", o:["Se cometa en explotaciones agrícolas o ganaderas y el valor de lo sustraído exceda de 400 euros","Se cometa de noche","Se trate de cualquier cantidad de productos agrícolas","Se cause una situación de desabastecimiento nacional"], e:"Art. 235.1.4.º: productos agrarios o ganaderos, o instrumentos o medios para obtenerlos, siempre que el delito se cometa en explotaciones agrícolas o ganaderas y el valor de lo sustraído exceda de 400 euros.", a:"Art. 235.1.4.º CP", f:"Texto legal y temario"},
  {id:"T14-018", p:"¿Cuál de las siguientes NO es una circunstancia agravante del hurto del artículo 235.1 CP?", o:["Que el hurto se cometa en domicilio ajeno","Que se sustraigan cosas de valor artístico, histórico, cultural o científico","Que se trate de cosas de primera necesidad y se cause una situación de desabastecimiento","Que el culpable actúe como miembro de una organización o grupo criminal dedicado a delitos del Título XIII"], e:"El lugar de comisión (domicilio) no aparece entre las diez circunstancias del art. 235.1. Las otras son los numerales 1.º, 2.º y 9.º.", a:"Art. 235.1 CP", f:"Texto legal"},
  {id:"T14-019", p:"Según el artículo 235.2 CP, si concurren dos o más circunstancias del apartado 1:", o:["La pena se impondrá en su mitad superior","Se impondrá la pena superior en grado","Se aplicará la pena de dos a cinco años","Se sumarán las penas"], e:"Art. 235.2: «La pena señalada en el apartado anterior se impondrá en su mitad superior cuando concurrieran dos o más de las circunstancias previstas en el mismo».", a:"Art. 235.2 CP", f:"Texto legal"},
  {id:"T14-020", p:"Según el artículo 236.1 CP, el dueño de una cosa mueble que la sustrae de quien la tiene legítimamente en su poder, con perjuicio de este o de un tercero, será castigado con:", o:["Multa de tres a doce meses","Multa de uno a tres meses","Prisión de seis a dieciocho meses","No es delito, por ser el dueño"], e:"Art. 236.1 (hurto de cosa propia o «furtum possessionis»): multa de tres a doce meses. Si el valor no excede de 400 euros, multa de uno a tres meses (236.2).", a:"Art. 236.1 CP", f:"Texto legal"},
  {id:"T14-021", p:"Según el artículo 236.2 CP, si el valor de la cosa propia sustraída no excede de 400 euros, la pena es:", o:["Multa de uno a tres meses","Multa de tres a doce meses","Multa de uno a dos meses","Localización permanente"], e:"Art. 236.2: multa de uno a tres meses.", a:"Art. 236.2 CP", f:"Texto legal"},

  // --- ROBO (ARTS. 237-242) ---
  {id:"T14-022", p:"Según el artículo 237 CP, son reos del delito de robo los que, con ánimo de lucro, se apoderan de cosas muebles ajenas empleando:", o:["Fuerza en las cosas para acceder o abandonar el lugar donde están, o violencia o intimidación en las personas","Engaño bastante para producir error","Cualquier medio clandestino","Fuerza sobre la propia cosa sustraída"], e:"Art. 237: robo con fuerza en las cosas (para acceder o abandonar el lugar) o con violencia o intimidación en las personas, al cometer el delito, para proteger la huida o sobre quienes acudan en auxilio de la víctima o la persigan.", a:"Art. 237 CP", f:"Texto legal"},
  {id:"T14-023", p:"¿Cuál de las siguientes NO es una de las circunstancias del robo con fuerza en las cosas del artículo 238 CP?", o:["Nocturnidad","Escalamiento","Uso de llaves falsas","Inutilización de sistemas específicos de alarma o guarda"], e:"Art. 238: 1.º escalamiento; 2.º rompimiento de pared, techo o suelo, o fractura de puerta o ventana; 3.º fractura de armarios, arcas u objetos cerrados o forzamiento de sus cerraduras; 4.º uso de llaves falsas; 5.º inutilización de sistemas específicos de alarma o guarda.", a:"Art. 238 CP", f:"Texto legal"},
  {id:"T14-024", p:"¿Cuántas circunstancias de robo con fuerza en las cosas enumera el artículo 238 CP?", o:["Cinco","Cuatro","Seis","Tres"], e:"Son cinco (1.º a 5.º): escalamiento; rompimiento o fractura de puerta o ventana; fractura de muebles u objetos cerrados; llaves falsas; inutilización de alarmas.", a:"Art. 238 CP", f:"Texto legal"},
  {id:"T14-025", p:"Según el artículo 238.3.º CP, la fractura de armarios, arcas u objetos cerrados o el forzamiento de sus cerraduras es robo con fuerza:", o:["Tanto si se realiza en el lugar del robo como fuera de él","Solo si se realiza en el lugar del robo","Solo si el objeto es una caja fuerte","Solo si se emplean herramientas"], e:"Art. 238.3.º: «…para sustraer su contenido, sea en el lugar del robo o fuera del mismo».", a:"Art. 238.3.º CP", f:"Texto legal"},
  {id:"T14-026", p:"Según el artículo 239 CP, ¿cuál de los siguientes NO se considera llave falsa?", o:["La llave legítima que el propietario entrega voluntariamente al autor para abrir la cerradura","Las ganzúas u otros instrumentos análogos","Las llaves legítimas perdidas por el propietario","Las llaves legítimas obtenidas mediante una infracción penal"], e:"Art. 239: son llaves falsas las ganzúas o instrumentos análogos, las llaves legítimas perdidas o obtenidas por medio de una infracción penal, y cualesquiera otras que no sean las destinadas por el propietario para abrir la cerradura violentada.", a:"Art. 239 CP", f:"Texto legal"},
  {id:"T14-027", p:"A efectos del artículo 239 CP, ¿se consideran llaves las tarjetas magnéticas y los mandos de apertura a distancia?", o:["Sí: las tarjetas magnéticas o perforadas, los mandos o instrumentos de apertura a distancia y cualquier otro instrumento tecnológico de eficacia similar","No, solo las llaves metálicas","Solo las tarjetas magnéticas","Solo si se han clonado"], e:"Art. 239, último párrafo: «se consideran llaves las tarjetas, magnéticas o perforadas, los mandos o instrumentos de apertura a distancia y cualquier otro instrumento tecnológico de eficacia similar».", a:"Art. 239 CP", f:"Texto legal"},
  {id:"T14-028", p:"Según el artículo 240.1 CP, el robo con fuerza en las cosas se castiga con:", o:["Prisión de uno a tres años","Prisión de dos a cinco años","Prisión de seis a dieciocho meses","Prisión de dos a seis años"], e:"Art. 240.1: prisión de uno a tres años. Si concurre alguna circunstancia del art. 235, dos a cinco años (240.2).", a:"Art. 240.1 CP", f:"Texto legal"},
  {id:"T14-029", p:"Según el artículo 240.2 CP, si en el robo con fuerza en las cosas concurre alguna de las circunstancias del artículo 235, la pena es:", o:["Prisión de dos a cinco años","Prisión de uno a tres años en su mitad superior","Prisión de dos a seis años","Prisión de tres años y seis meses a cinco años"], e:"Art. 240.2: «Se impondrá la pena de prisión de dos a cinco años, cuando concurra alguna de las circunstancias previstas en el artículo 235».", a:"Art. 240.2 CP", f:"Texto legal"},
  {id:"T14-030", p:"Según el artículo 241.1 CP, el robo cometido en casa habitada, edificio o local abiertos al público, o en sus dependencias, se castiga con:", o:["Prisión de dos a cinco años","Prisión de uno a tres años","Prisión de tres años y seis meses a cinco años","Prisión de dos a seis años"], e:"Art. 241.1: prisión de dos a cinco años.", a:"Art. 241.1 CP", f:"Texto legal"},
  {id:"T14-031", p:"Según el artículo 241.1 CP, si el robo se comete en un establecimiento abierto al público fuera de las horas de apertura, la pena es:", o:["Prisión de uno a cinco años","Prisión de dos a cinco años","Prisión de uno a tres años","Prisión de dos a seis años"], e:"Art. 241.1, párrafo segundo: fuera de las horas de apertura, prisión de uno a cinco años.", a:"Art. 241.1, párrafo segundo, CP", f:"Texto legal"},
  {id:"T14-032", p:"Según el artículo 241.2 CP, ¿qué se considera casa habitada?", o:["Todo albergue que constituya morada de una o más personas, aunque accidentalmente se encuentren ausentes cuando tenga lugar el robo","Solo la vivienda en la que haya personas en el momento del robo","Cualquier edificio con licencia de primera ocupación","La vivienda habitual inscrita en el padrón"], e:"Art. 241.2: «Se considera casa habitada todo albergue que constituya morada de una o más personas, aunque accidentalmente se encuentren ausentes de ella cuando el robo tenga lugar».", a:"Art. 241.2 CP", f:"Texto legal"},
  {id:"T14-033", p:"Según el artículo 241.3 CP, ¿qué se consideran dependencias de casa habitada?", o:["Sus patios, garajes y demás departamentos o sitios cercados y contiguos al edificio, en comunicación interior con él y formando una unidad física","Cualquier finca de la misma propiedad","Los trasteros situados en otro edificio","Solo las habitaciones interiores de la vivienda"], e:"Art. 241.3: patios, garajes y demás departamentos o sitios cercados y contiguos al edificio, en comunicación interior con él y con el cual formen una unidad física.", a:"Art. 241.3 CP", f:"Texto legal"},
  {id:"T14-034", p:"Según el artículo 241.4 CP, el robo en casa habitada o local abierto al público que revista especial gravedad o en el que concurra alguna circunstancia del artículo 235 se castiga con:", o:["Prisión de dos a seis años","Prisión de dos a cinco años","Prisión de tres a seis años","Prisión de cuatro a ocho años"], e:"Art. 241.4: «Se impondrá una pena de dos a seis años de prisión…» por especial gravedad (forma de comisión o perjuicios) y, en todo caso, si concurre alguna circunstancia del art. 235.", a:"Art. 241.4 CP", f:"Texto legal"},
  {id:"T14-035", p:"Según el artículo 242.1 CP, el robo con violencia o intimidación en las personas se castiga con:", o:["Prisión de dos a cinco años, sin perjuicio de la pena que corresponda a los actos de violencia física","Prisión de uno a tres años","Prisión de tres años y seis meses a cinco años","Prisión de dos a seis años"], e:"Art. 242.1: prisión de dos a cinco años, sin perjuicio de la que pudiera corresponder a los actos de violencia física que se realicen.", a:"Art. 242.1 CP", f:"Texto legal"},
  {id:"T14-036", p:"Según el artículo 242.2 CP, el robo con violencia o intimidación cometido en casa habitada, edificio o local abiertos al público se castiga con:", o:["Prisión de tres años y seis meses a cinco años","Prisión de dos a cinco años","Prisión de dos a seis años","Prisión de cuatro a ocho años"], e:"Art. 242.2: prisión de tres años y seis meses a cinco años.", a:"Art. 242.2 CP", f:"Texto legal"},
  {id:"T14-037", p:"Según el artículo 242.3 CP, las penas del robo con violencia o intimidación se imponen en su mitad superior cuando:", o:["El delincuente use armas u otros medios igualmente peligrosos, al cometer el delito o para proteger la huida, o ataque a quienes acudan en auxilio de la víctima o le persigan","El robo se cometa de noche","La víctima sea mayor de edad","El botín supere los 400 euros"], e:"Art. 242.3: mitad superior cuando el delincuente hiciere uso de armas u otros medios igualmente peligrosos, al cometer el delito o para proteger la huida, y cuando atacare a quienes acudan en auxilio de la víctima o le persigan.", a:"Art. 242.3 CP", f:"Texto legal"},
  {id:"T14-038", p:"Según el artículo 242.4 CP, en atención a la menor entidad de la violencia o intimidación ejercidas y a las restantes circunstancias, puede imponerse:", o:["La pena inferior en grado","La pena en su mitad inferior","Una multa de seis a doce meses","La pena del hurto"], e:"Art. 242.4: «…podrá imponerse la pena inferior en grado a la prevista en los apartados anteriores».", a:"Art. 242.4 CP", f:"Texto legal"},
  {id:"T14-039", p:"Un individuo sustrae una cartera sin que la víctima lo note y, al ser perseguido por un viandante, le empuja violentamente para huir. ¿Qué delito comete?", o:["Robo con violencia (art. 242), porque la violencia se ejerce para proteger la huida sobre quien le persigue","Hurto, porque el apoderamiento fue sin violencia","Hurto y un delito leve de lesiones","Extorsión"], e:"El art. 237 considera robo la violencia o intimidación ejercida «al cometer el delito, para proteger la huida, o sobre los que acudiesen en auxilio de la víctima o que le persiguieren».", a:"Arts. 237 y 242 CP", f:"Texto legal"},
  {id:"T14-040", p:"Saltar la valla de una finca para acceder a ella y sustraer herramientas constituye robo con fuerza en las cosas por la circunstancia de:", o:["Escalamiento (art. 238.1.º)","Rompimiento de pared (art. 238.2.º)","Uso de llaves falsas (art. 238.4.º)","Inutilización de alarma (art. 238.5.º)"], e:"Acceder al lugar salvando un obstáculo por una vía no destinada a ese fin es escalamiento, la circunstancia 1.ª del art. 238.", a:"Art. 238.1.º CP", f:"Texto legal y temario"},
  {id:"T14-041", p:"¿Qué tipo de delito es el robo con violencia o intimidación del artículo 242.1 CP (prisión de dos a cinco años) según el artículo 13 CP?", o:["Menos grave","Grave","Leve","Grave si hay lesiones"], e:"La prisión de tres meses hasta cinco años es pena menos grave (art. 33.3.a). Por tanto, el delito es menos grave.", a:"Arts. 13, 33 y 242.1 CP", f:"Texto legal y temario"},

  // --- EXTORSIÓN (ART. 243) ---
  {id:"T14-042", p:"Según el artículo 243 CP, comete extorsión quien, con ánimo de lucro:", o:["Obligue a otro, con violencia o intimidación, a realizar u omitir un acto o negocio jurídico en perjuicio de su patrimonio o del de un tercero","Utilice engaño bastante para producir error en otro","Se apropie de dinero recibido en depósito","Amenace a otro con revelar secretos, sin pedir nada a cambio"], e:"Art. 243: obligar con violencia o intimidación a realizar u omitir un acto o negocio jurídico en perjuicio del patrimonio propio o de un tercero.", a:"Art. 243 CP", f:"Texto legal"},
  {id:"T14-043", p:"¿Con qué pena castiga el artículo 243 CP la extorsión?", o:["Prisión de uno a cinco años, sin perjuicio de las penas por los actos de violencia física","Prisión de dos a cinco años","Prisión de seis meses a tres años","Prisión de uno a tres años"], e:"Art. 243: prisión de uno a cinco años, sin perjuicio de las que pudieran imponerse por los actos de violencia física realizados.", a:"Art. 243 CP", f:"Texto legal"},
  {id:"T14-044", p:"¿En qué capítulo del Título XIII se regula la extorsión?", o:["Capítulo III","Capítulo II","Capítulo IV","Capítulo VI"], e:"La extorsión forma el Capítulo III (art. 243).", a:"Título XIII, Capítulo III CP", f:"Texto legal"},

  // --- ROBO Y HURTO DE USO DE VEHÍCULOS (ART. 244) ---
  {id:"T14-045", p:"Según el artículo 244.1 CP, quien sustrae o utiliza sin autorización un vehículo a motor o ciclomotor ajeno, sin ánimo de apropiárselo, y lo restituye en un plazo no superior a 48 horas, será castigado con:", o:["Trabajos en beneficio de la comunidad de treinta y uno a noventa días o multa de dos a doce meses","Prisión de seis a dieciocho meses","Multa de uno a tres meses","Prisión de uno a tres años"], e:"Art. 244.1: trabajos en beneficio de la comunidad de treinta y uno a noventa días o multa de dos a doce meses, sin que la pena pueda ser igual o superior a la que correspondería si se apropiara definitivamente del vehículo.", a:"Art. 244.1 CP", f:"Texto legal"},
  {id:"T14-046", p:"¿En qué plazo máximo debe restituirse el vehículo para aplicar el hurto o robo de uso del artículo 244 CP?", o:["48 horas","24 horas","72 horas","Siete días"], e:"Art. 244.1: «…si lo restituyera, directa o indirectamente, en un plazo no superior a cuarenta y ocho horas».", a:"Art. 244.1 CP", f:"Texto legal"},
  {id:"T14-047", p:"Según el artículo 244.3 CP, si no se restituye el vehículo en el plazo señalado:", o:["El hecho se castiga como hurto o robo, en sus respectivos casos","Se impone la pena del 244.1 en su mitad superior","Se impone la pena superior en grado","El hecho queda impune"], e:"Art. 244.3: «De no efectuarse la restitución en el plazo señalado, se castigará el hecho como hurto o robo en sus respectivos casos».", a:"Art. 244.3 CP", f:"Texto legal"},
  {id:"T14-048", p:"Según el artículo 244.2 CP, si el hurto de uso del vehículo se ejecuta empleando fuerza en las cosas:", o:["La pena se aplica en su mitad superior","Se aplican las penas del robo con fuerza","Se impone la pena superior en grado","Se aplican las penas del artículo 242"], e:"Art. 244.2: «Si el hecho se ejecutare empleando fuerza en las cosas, la pena se aplicará en su mitad superior».", a:"Art. 244.2 CP", f:"Texto legal"},
  {id:"T14-049", p:"Según el artículo 244.4 CP, si el uso del vehículo se comete con violencia o intimidación en las personas:", o:["Se impondrán, en todo caso, las penas del artículo 242 (robo con violencia o intimidación)","Se impondrá la pena del 244.1 en su mitad superior","Se impondrá la pena del artículo 240","Se impondrán trabajos en beneficio de la comunidad"], e:"Art. 244.4: «Si el hecho se cometiere con violencia o intimidación en las personas, se impondrán, en todo caso, las penas del artículo 242».", a:"Art. 244.4 CP", f:"Texto legal"},
  {id:"T14-050", p:"¿Qué vehículos pueden ser objeto del delito de robo y hurto de uso del artículo 244 CP?", o:["Vehículos a motor o ciclomotores ajenos","Cualquier vehículo, incluidas las bicicletas","Solo turismos","Solo vehículos matriculados en España"], e:"Art. 244.1: «…un vehículo a motor o ciclomotor ajenos…».", a:"Art. 244.1 CP", f:"Texto legal"},
  {id:"T14-051", p:"¿Qué elemento subjetivo distingue el hurto de uso de vehículo (art. 244) del hurto común (art. 234)?", o:["La ausencia de ánimo de apropiarse definitivamente del vehículo","La ausencia de ánimo de lucro","El uso de violencia","Que el vehículo sea de un familiar"], e:"El art. 244.1 exige actuar «sin ánimo de apropiárselo» y devolverlo en 48 horas. Si hay ánimo de apropiación o no se restituye, es hurto o robo.", a:"Arts. 234 y 244 CP", f:"Texto legal"},

  // --- DAÑOS (ARTS. 263-267) ---
  {id:"T14-052", p:"Según el artículo 263.1 CP, quien cause daños en propiedad ajena no comprendidos en otros títulos será castigado con:", o:["Multa de seis a veinticuatro meses, atendidas la condición económica de la víctima y la cuantía del daño","Prisión de uno a tres años","Multa de tres a doce meses","Prisión de seis meses a tres años"], e:"Art. 263.1: multa de seis a veinticuatro meses. Si el daño no excede de 400 euros, multa de uno a tres meses.", a:"Art. 263.1 CP", f:"Texto legal"},
  {id:"T14-053", p:"Según el artículo 263.1 CP, si la cuantía del daño no excede de 400 euros, la pena es:", o:["Multa de uno a tres meses","Multa de seis a veinticuatro meses","Multa de tres a seis meses","Localización permanente de dos a seis días"], e:"Art. 263.1, párrafo segundo: multa de uno a tres meses.", a:"Art. 263.1 CP", f:"Texto legal"},
  {id:"T14-054", p:"Según el artículo 263.2 CP, los daños agravados se castigan con:", o:["Prisión de uno a tres años y multa de doce a veinticuatro meses","Prisión de dos a cuatro años","Multa de doce a veinticuatro meses","Prisión de seis meses a tres años"], e:"Art. 263.2: prisión de uno a tres años y multa de doce a veinticuatro meses.", a:"Art. 263.2 CP", f:"Texto legal"},
  {id:"T14-055", p:"Unos jóvenes rompen varios bancos y papeleras de un parque público. ¿Qué circunstancia del artículo 263.2 CP concurre?", o:["Que los daños afecten a bienes de dominio o uso público o comunal (4.º)","Que se realicen para impedir el libre ejercicio de la autoridad (1.º)","Que arruinen al perjudicado (5.º)","Ninguna: es el tipo básico"], e:"El art. 263.2.4.º agrava los daños que afecten a bienes de dominio o uso público o comunal.", a:"Art. 263.2.4.º CP", f:"Texto legal"},
  {id:"T14-056", p:"¿Cuál de los siguientes NO es un supuesto de daños agravados del artículo 263.2 CP?", o:["Que se causen de noche","Que se cause infección o contagio de ganado","Que se empleen sustancias venenosas o corrosivas","Que arruinen al perjudicado o lo coloquen en grave situación económica"], e:"Art. 263.2: 1.º impedir el ejercicio de la autoridad o represalia; 2.º infección o contagio de ganado; 3.º sustancias venenosas o corrosivas; 4.º bienes de dominio o uso público o comunal; 5.º arruinar al perjudicado; 6.º daños de especial gravedad o que afecten a intereses generales.", a:"Art. 263.2 CP", f:"Texto legal"},
  {id:"T14-057", p:"Según el artículo 264.1 CP, quien sin autorización y de manera grave borre, dañe o haga inaccesibles datos, programas informáticos o documentos electrónicos ajenos, con resultado grave, será castigado con:", o:["Prisión de seis meses a tres años","Prisión de dos a cinco años","Multa de seis a veinticuatro meses","Prisión de uno a tres años y multa"], e:"Art. 264.1: prisión de seis meses a tres años.", a:"Art. 264.1 CP", f:"Texto legal"},
  {id:"T14-058", p:"Según el artículo 264 bis.1 CP, obstaculizar o interrumpir de manera grave el funcionamiento de un sistema informático ajeno se castiga con:", o:["Prisión de seis meses a tres años","Prisión de tres a ocho años","Prisión de seis meses a dos años o multa de tres a dieciocho meses","Multa de doce a veinticuatro meses"], e:"Art. 264 bis.1: prisión de seis meses a tres años. Con las circunstancias del art. 264.2, tres a ocho años y multa del triplo al décuplo del perjuicio (264 bis.2).", a:"Art. 264 bis.1 CP", f:"Texto legal"},
  {id:"T14-059", p:"Según el artículo 265 CP, quien destruya, dañe gravemente o inutilice instalaciones, medios o recursos afectados al servicio de las Fuerzas Armadas o de las Fuerzas y Cuerpos de Seguridad será castigado, si el daño excede de mil euros, con:", o:["Prisión de dos a cuatro años","Prisión de uno a tres años","Prisión de cuatro a ocho años","Multa de doce a veinticuatro meses"], e:"Art. 265: prisión de dos a cuatro años si el daño causado excediere de mil euros.", a:"Art. 265 CP", f:"Texto legal"},
  {id:"T14-060", p:"Según el artículo 266.1 CP, los daños del artículo 263.1 cometidos mediante incendio, explosiones u otro medio de similar potencia destructiva se castigan con:", o:["Prisión de uno a tres años","Prisión de tres a cinco años y multa de doce a veinticuatro meses","Prisión de cuatro a ocho años","Prisión de dos a cuatro años"], e:"Art. 266.1: prisión de uno a tres años. Si son los daños del 263.2, tres a cinco años y multa (266.2); si son los de los arts. 265, 323 y 560, cuatro a ocho años (266.3).", a:"Art. 266.1 CP", f:"Texto legal"},
  {id:"T14-061", p:"Según el artículo 267 CP, los daños causados por imprudencia grave son delito cuando su cuantía supere:", o:["80.000 euros","400 euros","50.000 euros","1.000 euros"], e:"Art. 267: daños por imprudencia grave en cuantía superior a 80.000 euros, castigados con multa de tres a nueve meses.", a:"Art. 267 CP", f:"Texto legal"},
  {id:"T14-062", p:"Respecto a los daños por imprudencia grave del artículo 267 CP, ¿qué es correcto?", o:["Solo son perseguibles previa denuncia de la persona agraviada o su representante legal, y el perdón del ofendido extingue la acción penal","Son perseguibles de oficio y el perdón no extingue la acción","Se castigan con prisión de uno a tres años","Solo los persigue el Ministerio Fiscal"], e:"Art. 267: requieren denuncia de la persona agraviada o de su representante legal (el Ministerio Fiscal puede denunciar si es menor, persona con discapacidad necesitada de especial protección o desvalida), y el perdón del ofendido extingue la acción penal.", a:"Art. 267 CP", f:"Texto legal"},
  {id:"T14-063", p:"¿Con qué pena castiga el artículo 267 CP los daños por imprudencia grave de más de 80.000 euros?", o:["Multa de tres a nueve meses","Multa de seis a veinticuatro meses","Prisión de seis meses a un año","Multa de uno a tres meses"], e:"Art. 267: multa de tres a nueve meses, atendiendo a la importancia de los daños.", a:"Art. 267 CP", f:"Texto legal"},

  // --- DISPOSICIONES COMUNES (ARTS. 268-269) ---
  {id:"T14-064", p:"Según el artículo 268.1 CP, ¿quiénes están exentos de responsabilidad criminal, y sujetos solo a la civil, por los delitos patrimoniales que se causen entre sí?", o:["Los cónyuges no separados legalmente o de hecho ni en proceso de separación, divorcio o nulidad; los ascendientes, descendientes y hermanos; y los afines en primer grado si viven juntos","Todos los familiares hasta el cuarto grado","Los cónyuges, aunque estén separados","Solo los padres respecto de los hijos menores"], e:"Art. 268.1 (excusa absolutoria): cónyuges no separados legalmente o de hecho ni en proceso de separación, divorcio o nulidad; ascendientes, descendientes y hermanos por naturaleza o adopción; y afines en primer grado si viviesen juntos.", a:"Art. 268.1 CP", f:"Texto legal"},
  {id:"T14-065", p:"¿Cuándo NO se aplica la exención del artículo 268.1 CP entre parientes?", o:["Cuando concurra violencia o intimidación, o abuso de la vulnerabilidad de la víctima por razón de edad o discapacidad","Cuando la cuantía supere los 400 euros","Cuando los parientes no vivan juntos, en todo caso","Cuando el delito sea de daños"], e:"Art. 268.1: la exención opera «siempre que no concurra violencia o intimidación, o abuso de la vulnerabilidad de la víctima, ya sea por razón de edad, o por tratarse de una persona con discapacidad».", a:"Art. 268.1 CP", f:"Texto legal"},
  {id:"T14-066", p:"Según el artículo 268.2 CP, la exención de responsabilidad entre parientes:", o:["No es aplicable a los extraños que participen en el delito","Se extiende a todos los partícipes","Se extiende a los amigos íntimos","Solo se aplica a los autores, no a los cómplices"], e:"Art. 268.2: «Esta disposición no es aplicable a los extraños que participaren en el delito».", a:"Art. 268.2 CP", f:"Texto legal"},
  {id:"T14-067", p:"Un hijo sustrae 300 euros de la cartera de su padre, con quien convive, sin violencia ni intimidación. ¿Qué responsabilidad tiene?", o:["Está exento de responsabilidad criminal y sujeto únicamente a la civil (art. 268.1)","Comete un delito leve de hurto","Comete un delito de apropiación indebida","Comete un hurto agravado por parentesco"], e:"El art. 268.1 exime de responsabilidad criminal a descendientes y ascendientes por los delitos patrimoniales entre sí, sin violencia, intimidación ni abuso de vulnerabilidad. Queda la responsabilidad civil.", a:"Art. 268.1 CP", f:"Texto legal"},
  {id:"T14-068", p:"Según el artículo 269 CP, la provocación, la conspiración y la proposición para cometer delitos de robo, extorsión, estafa o apropiación indebida se castigan con:", o:["La pena inferior en uno o dos grados a la del delito correspondiente","La misma pena del delito consumado","La pena inferior en grado, en todo caso","Multa de uno a tres meses"], e:"Art. 269: «…serán castigadas con la pena inferior en uno o dos grados a la del delito correspondiente».", a:"Art. 269 CP", f:"Texto legal"},
  {id:"T14-069", p:"¿Para cuál de los siguientes delitos NO castiga el artículo 269 CP los actos preparatorios (provocación, conspiración y proposición)?", o:["El hurto","El robo","La extorsión","La estafa"], e:"El art. 269 solo se refiere al robo, la extorsión, la estafa y la apropiación indebida. El hurto no está.", a:"Art. 269 CP", f:"Texto legal"},

  // --- USURPACIÓN (ARTS. 245-247) ---
  {id:"T14-070", p:"Según el artículo 245.1 CP, quien con violencia o intimidación en las personas ocupe un inmueble o usurpe un derecho real inmobiliario ajeno será castigado, además de con las penas por las violencias ejercidas, con:", o:["Prisión de uno a dos años","Multa de tres a seis meses","Prisión de dos a cinco años","Prisión de seis meses a dos años"], e:"Art. 245.1: prisión de uno a dos años, que se fijará teniendo en cuenta la utilidad obtenida y el daño causado.", a:"Art. 245.1 CP", f:"Texto legal"},
  {id:"T14-071", p:"Según el artículo 245.2 CP, quien ocupe sin autorización un inmueble, vivienda o edificio ajeno que NO constituya morada, o se mantenga en él contra la voluntad de su titular, será castigado con:", o:["Multa de tres a seis meses","Prisión de uno a dos años","Multa de uno a tres meses","Prisión de seis meses a un año"], e:"Art. 245.2: multa de tres a seis meses. Si el inmueble constituye morada, los hechos encajan en el allanamiento de morada (art. 202), no en la usurpación.", a:"Art. 245.2 CP", f:"Texto legal"},
  {id:"T14-072", p:"Según el artículo 246 CP, alterar términos, lindes o mojones destinados a fijar los límites de propiedades se castiga con:", o:["Multa de tres a dieciocho meses (de uno a tres meses si la utilidad no excede de 400 euros)","Multa de tres a seis meses","Prisión de seis meses a un año","Prisión de uno a dos años"], e:"Art. 246: multa de tres a dieciocho meses; si la utilidad reportada no excede de 400 euros, multa de uno a tres meses.", a:"Art. 246 CP", f:"Texto legal"},
  {id:"T14-073", p:"Según el artículo 247 CP, quien sin autorización distraiga las aguas de uso público o privativo de su curso o de su embalse será castigado con:", o:["Multa de tres a seis meses","Multa de tres a dieciocho meses","Prisión de seis meses a un año","Multa de seis a doce meses"], e:"Art. 247: multa de tres a seis meses; si la utilidad no excede de 400 euros, multa de uno a tres meses.", a:"Art. 247 CP", f:"Texto legal"},

  // --- ESTAFAS (ARTS. 248-251 BIS) ---
  {id:"T14-074", p:"Según el artículo 248 CP, cometen estafa los que, con ánimo de lucro:", o:["Utilizan engaño bastante para producir error en otro, induciéndolo a realizar un acto de disposición en perjuicio propio o ajeno","Se apropian de dinero recibido en depósito","Toman cosas muebles ajenas sin la voluntad de su dueño","Obligan a otro con intimidación a realizar un negocio jurídico"], e:"Art. 248: «Cometen estafa los que, con ánimo de lucro, utilizaren engaño bastante para producir error en otro, induciéndolo a realizar un acto de disposición en perjuicio propio o ajeno».", a:"Art. 248 CP", f:"Texto legal"},
  {id:"T14-075", p:"¿Con qué pena se castiga la estafa básica del artículo 248 CP?", o:["Prisión de seis meses a tres años","Prisión de uno a seis años y multa de seis a doce meses","Prisión de seis a dieciocho meses","Prisión de uno a cuatro años"], e:"Art. 248: «Los reos de estafa serán castigados con la pena de prisión de seis meses a tres años».", a:"Art. 248 CP", f:"Texto legal"},
  {id:"T14-076", p:"Según el artículo 248 CP, si la cuantía de lo defraudado no excede de 400 euros (y no concurren circunstancias del 250), la pena es:", o:["Multa de uno a tres meses","Multa de tres a doce meses","Prisión de seis meses a tres años","Multa de uno a dos meses"], e:"Art. 248: multa de uno a tres meses, salvo que concurra alguna circunstancia del art. 250. Pero si el culpable tiene al menos tres condenas ejecutorias por delitos de la misma naturaleza del Capítulo VI, siendo al menos una leve, se impone la pena de prisión de seis meses a tres años (regla introducida por la LO 1/2026).", a:"Art. 248 CP", f:"Texto legal"},
  {id:"T14-077", p:"Según el artículo 249.1.a) CP, también son reos de estafa los que, con ánimo de lucro:", o:["Valiéndose de una manipulación informática o artificio semejante, consigan una transferencia no consentida de un activo patrimonial en perjuicio de otro","Entren sin autorización en un sistema informático","Copien programas de ordenador sin licencia","Envíen correos masivos no solicitados"], e:"Art. 249.1.a): estafa informática. Se castiga con prisión de seis meses a tres años.", a:"Art. 249.1.a) CP", f:"Texto legal"},
  {id:"T14-078", p:"Utilizar fraudulentamente una tarjeta de crédito ajena para realizar compras en perjuicio de su titular constituye:", o:["Estafa del artículo 249.1.b) CP","Hurto del artículo 234 CP","Apropiación indebida del artículo 253 CP","Falsedad documental"], e:"Art. 249.1.b): quienes, utilizando de forma fraudulenta tarjetas de crédito o débito, cheques de viaje u otros instrumentos de pago distintos del efectivo o sus datos, realicen operaciones en perjuicio de su titular o de un tercero.", a:"Art. 249.1.b) CP", f:"Texto legal"},
  {id:"T14-079", p:"Según el artículo 250.1 CP, la estafa agravada se castiga con:", o:["Prisión de uno a seis años y multa de seis a doce meses","Prisión de cuatro a ocho años y multa de doce a veinticuatro meses","Prisión de seis meses a tres años","Prisión de dos a cinco años"], e:"Art. 250.1: prisión de uno a seis años y multa de seis a doce meses.", a:"Art. 250.1 CP", f:"Texto legal"},
  {id:"T14-080", p:"Según el artículo 250.1.5.º CP, la estafa se agrava cuando el valor de la defraudación supere:", o:["50.000 euros, o afecte a un elevado número de personas","400 euros","120.000 euros","250.000 euros"], e:"Art. 250.1.5.º: más de 50.000 euros o un elevado número de personas. Por encima de 250.000 euros se aplica el 250.2 (cuatro a ocho años).", a:"Art. 250.1.5.º CP", f:"Texto legal"},
  {id:"T14-081", p:"Según el artículo 250.2 CP, cuando el valor de la defraudación supera los 250.000 euros, la pena es:", o:["Prisión de cuatro a ocho años y multa de doce a veinticuatro meses","Prisión de uno a seis años y multa de seis a doce meses","Prisión de dos a seis años","Prisión de seis a diez años"], e:"Art. 250.2: prisión de cuatro a ocho años y multa de doce a veinticuatro meses. La misma pena se aplica cuando concurren los numerales 4.º, 5.º, 6.º o 7.º con el 1.º.", a:"Art. 250.2 CP", f:"Texto legal"},
  {id:"T14-082", p:"Según el artículo 250.1.7.º CP, ¿qué es la estafa procesal?", o:["Manipular las pruebas o emplear otro fraude procesal análogo en un procedimiento judicial, provocando error en el juez y llevándole a dictar una resolución que perjudique económicamente a la otra parte o a un tercero","Engañar a un notario para otorgar una escritura","Presentar una denuncia falsa","Mentir como testigo en un juicio"], e:"Art. 250.1.7.º: incurren en estafa procesal los que, en un procedimiento judicial, manipulen las pruebas o empleen otro fraude procesal análogo, provocando error en el juez o tribunal y llevándole a dictar una resolución que perjudique los intereses económicos de la otra parte o de un tercero.", a:"Art. 250.1.7.º CP", f:"Texto legal"},
  {id:"T14-083", p:"Según el artículo 251.1.º CP, quien, atribuyéndose falsamente facultad de disposición sobre una cosa, la enajene, grave o arriende a otro en su perjuicio, será castigado con:", o:["Prisión de uno a cuatro años","Prisión de seis meses a tres años","Prisión de uno a seis años","Multa de tres a doce meses"], e:"Art. 251: prisión de uno a cuatro años para la falsa atribución de facultad de disposición (1.º), la disposición ocultando cargas o la doble venta (2.º) y el contrato simulado (3.º).", a:"Art. 251 CP", f:"Texto legal"},
  {id:"T14-084", p:"Vender como libre una vivienda ocultando que tiene una hipoteca, en perjuicio del comprador, constituye:", o:["El delito del artículo 251.2.º CP (prisión de uno a cuatro años)","Apropiación indebida","Administración desleal","Estafa procesal"], e:"Art. 251.2.º: «El que dispusiere de una cosa mueble o inmueble ocultando la existencia de cualquier carga sobre la misma…».", a:"Art. 251.2.º CP", f:"Texto legal"},

  // --- ADMINISTRACIÓN DESLEAL Y APROPIACIÓN INDEBIDA ---
  {id:"T14-085", p:"Según el artículo 252.1 CP, ¿con qué penas se castiga la administración desleal?", o:["Con las penas del artículo 248 o, en su caso, del artículo 250","Con prisión de uno a cuatro años","Con multa de tres a doce meses","Con prisión de dos a cinco años"], e:"Art. 252.1: «Serán castigados con las penas del artículo 248 o, en su caso, con las del artículo 250…» quienes, con facultades para administrar un patrimonio ajeno, las infrinjan excediéndose en su ejercicio y causen un perjuicio. Si el perjuicio no excede de 400 euros, multa de uno a tres meses.", a:"Art. 252 CP", f:"Texto legal"},
  {id:"T14-086", p:"Según el artículo 253.1 CP, comete apropiación indebida quien, en perjuicio de otro, se apropia para sí o para un tercero de dinero, efectos, valores o cualquier otra cosa mueble que:", o:["Haya recibido en depósito, comisión o custodia, o que se le haya confiado con obligación de entregarlo o devolverlo, o niegue haberlo recibido","Haya encontrado perdido en la vía pública","Haya tomado sin la voluntad de su dueño","Haya obtenido mediante engaño"], e:"Art. 253.1: cosas recibidas en depósito, comisión o custodia, o confiadas en virtud de cualquier título que obligue a entregarlas o devolverlas, o negar haberlas recibido. Penas del art. 248 o, en su caso, del 250.", a:"Art. 253.1 CP", f:"Texto legal"},
  {id:"T14-087", p:"Según el artículo 254.1 CP, quien, fuera de los supuestos del artículo 253, se apropie de una cosa mueble ajena (por ejemplo, una cartera encontrada) será castigado con:", o:["Multa de tres a seis meses (prisión de seis meses a dos años si es de valor artístico, histórico, cultural o científico)","Las penas del artículo 248","Multa de uno a tres meses en todo caso","Prisión de seis a dieciocho meses"], e:"Art. 254.1: multa de tres a seis meses; prisión de seis meses a dos años si son cosas de valor artístico, histórico, cultural o científico. Si la cuantía no excede de 400 euros, multa de uno a dos meses (254.2).", a:"Art. 254 CP", f:"Texto legal"},
  {id:"T14-088", p:"Según el artículo 254.2 CP, si la cuantía de la cosa apropiada fuera de los supuestos del 253 no excede de 400 euros, la pena es:", o:["Multa de uno a dos meses","Multa de uno a tres meses","Multa de tres a seis meses","Localización permanente"], e:"Art. 254.2: multa de uno a dos meses. Ojo: en hurto, estafa o apropiación del 253 es de uno a tres meses.", a:"Art. 254.2 CP", f:"Texto legal"},

  // --- DEFRAUDACIONES DE FLUIDO ELÉCTRICO Y ANÁLOGAS ---
  {id:"T14-089", p:"Según el artículo 255.1 CP, la defraudación de energía eléctrica, gas, agua, telecomunicaciones u otro fluido ajeno se castiga con:", o:["Multa de tres a doce meses","Multa de uno a tres meses","Prisión de seis a dieciocho meses","Prisión de seis meses a tres años"], e:"Art. 255.1: multa de tres a doce meses, si se comete valiéndose de mecanismos instalados para defraudar, alterando maliciosamente los contadores o con otros medios clandestinos. Si no excede de 400 euros, multa de uno a tres meses (255.2).", a:"Art. 255.1 CP", f:"Texto legal"},
  {id:"T14-090", p:"Según el artículo 255.3 CP, añadido por la LO 1/2026, si la defraudación de energía eléctrica, cualquiera que sea su cuantía, se comete para abastecer instalaciones usadas para cometer delitos del artículo 368 (tráfico de drogas), la pena es:", o:["Prisión de seis a dieciocho meses o multa de doce a veinticuatro meses","Multa de tres a doce meses","Prisión de uno a tres años","Multa de uno a tres meses"], e:"Art. 255.3: prisión de seis a dieciocho meses o multa de doce a veinticuatro meses.", a:"Art. 255.3 CP (LO 1/2026)", f:"Texto legal"},
  {id:"T14-091", p:"¿Cuál de los siguientes NO es un medio de defraudación de fluidos previsto en el artículo 255.1 CP?", o:["Consumir más energía de la contratada sin manipular nada","Valerse de mecanismos instalados para realizar la defraudación","Alterar maliciosamente las indicaciones o aparatos contadores","Emplear cualesquiera otros medios clandestinos"], e:"Art. 255.1: 1.º mecanismos instalados para defraudar; 2.º alterar maliciosamente los contadores; 3.º cualesquiera otros medios clandestinos.", a:"Art. 255.1 CP", f:"Texto legal"},
  {id:"T14-092", p:"Según el artículo 256.1 CP, quien use un equipo terminal de telecomunicación sin consentimiento de su titular y le cause un perjuicio económico será castigado con:", o:["Multa de tres a doce meses (de uno a tres meses si el perjuicio no excede de 400 euros)","Prisión de seis meses a tres años","Multa de uno a tres meses en todo caso","Prisión de seis a dieciocho meses"], e:"Art. 256: multa de tres a doce meses; si el perjuicio no excede de 400 euros, multa de uno a tres meses.", a:"Art. 256 CP", f:"Texto legal"},

  // --- PROPIEDAD INTELECTUAL (ARTS. 270-272) ---
  {id:"T14-093", p:"Según el artículo 270.1 CP, quien con ánimo de obtener un beneficio económico y en perjuicio de tercero reproduzca, plagie, distribuya o comunique públicamente una obra sin autorización será castigado con:", o:["Prisión de seis meses a cuatro años y multa de doce a veinticuatro meses","Prisión de seis meses a dos años y multa de 12 a 24 meses","Prisión de dos a seis años","Multa de seis a doce meses"], e:"Art. 270.1: prisión de seis meses a cuatro años y multa de doce a veinticuatro meses.", a:"Art. 270.1 CP", f:"Texto legal"},
  {id:"T14-094", p:"Según el artículo 270.4 CP, la distribución o comercialización ambulante o meramente ocasional (el llamado «top manta») de obras protegidas se castiga con:", o:["Prisión de seis meses a dos años; el juez puede imponer multa de uno a seis meses o trabajos en beneficio de la comunidad de 31 a 60 días si el beneficio es reducido y no concurren circunstancias del art. 271","Prisión de seis meses a cuatro años y multa","Multa de uno a tres meses en todo caso","No es delito, solo infracción administrativa"], e:"Art. 270.4: prisión de seis meses a dos años. Atendidas las características del culpable y la reducida cuantía del beneficio, si no concurre ninguna circunstancia del art. 271, multa de uno a seis meses o trabajos de treinta y uno a sesenta días.", a:"Art. 270.4 CP", f:"Texto legal"},
  {id:"T14-095", p:"Según el artículo 271 CP, los delitos contra la propiedad intelectual se agravan (prisión de dos a seis años, multa de dieciocho a treinta y seis meses e inhabilitación especial de dos a cinco años) cuando, entre otros supuestos:", o:["Se utilice a menores de 18 años para cometer estos delitos","El autor sea extranjero","La obra sea de un autor fallecido","Se cometa a través de internet"], e:"Art. 271: a) beneficio de especial trascendencia económica; b) especial gravedad de los hechos; c) pertenencia a organización o asociación; d) utilización de menores de 18 años.", a:"Art. 271 CP", f:"Texto legal"},
  {id:"T14-096", p:"Según el artículo 272.2 CP, en caso de sentencia condenatoria por delitos contra la propiedad intelectual, el juez puede decretar:", o:["La publicación de la sentencia, a costa del infractor, en un periódico oficial","La clausura definitiva del establecimiento","La expulsión del infractor extranjero","La disolución de la persona jurídica en todo caso"], e:"Art. 272.2: «…el Juez o Tribunal podrá decretar la publicación de ésta, a costa del infractor, en un periódico oficial».", a:"Art. 272.2 CP", f:"Texto legal"},

  // --- PROPIEDAD INDUSTRIAL (ARTS. 273-277) ---
  {id:"T14-097", p:"Según el artículo 274.1 CP, quien con fines industriales o comerciales y sin consentimiento del titular de una marca registrada fabrique, produzca o importe productos que incorporen un signo distintivo idéntico o confundible será castigado con:", o:["Prisión de uno a cuatro años y multa de doce a veinticuatro meses","Prisión de seis meses a tres años","Prisión de seis meses a dos años y multa de 12 a 24 meses","Prisión de dos a seis años"], e:"Art. 274.1: prisión de uno a cuatro años y multa de doce a veinticuatro meses. La venta al por menor se castiga con seis meses a tres años (274.2).", a:"Art. 274.1 CP", f:"Texto legal"},
  {id:"T14-098", p:"Según el artículo 274.3 CP, la venta ambulante u ocasional de productos con marcas falsificadas se castiga con:", o:["Prisión de seis meses a dos años, pudiendo imponerse multa de uno a seis meses o trabajos en beneficio de la comunidad de 31 a 60 días en ciertos casos","Prisión de uno a cuatro años","Multa de uno a tres meses","Prisión de seis meses a tres años"], e:"Art. 274.3: prisión de seis meses a dos años. Atendidas las características del culpable y el reducido beneficio, si no concurre ninguna circunstancia del art. 276, el juez puede imponer multa de uno a seis meses o trabajos de treinta y uno a sesenta días.", a:"Art. 274.3 CP", f:"Texto legal"},
  {id:"T14-099", p:"Según el artículo 273.1 CP, quien con fines industriales o comerciales y sin consentimiento del titular de una patente o modelo de utilidad fabrique, importe o comercialice objetos amparados por ella, conociendo su registro, será castigado con:", o:["Prisión de seis meses a dos años y multa de 12 a 24 meses","Prisión de uno a cuatro años y multa de doce a veinticuatro meses","Prisión de dos a seis años","Prisión de seis meses a cuatro años"], e:"Art. 273.1: prisión de seis meses a dos años y multa de 12 a 24 meses.", a:"Art. 273.1 CP", f:"Texto legal"},
  {id:"T14-100", p:"Según el artículo 277 CP, divulgar intencionadamente la invención objeto de una solicitud de patente secreta, en perjuicio de la defensa nacional, se castiga con:", o:["Prisión de seis meses a dos años y multa de seis a veinticuatro meses","Prisión de dos a seis años","Prisión de uno a cuatro años","Multa de doce a veinticuatro meses"], e:"Art. 277: prisión de seis meses a dos años y multa de seis a veinticuatro meses. Por otro lado, el art. 275 castiga con las penas del 274 el uso no autorizado de denominaciones de origen o indicaciones geográficas protegidas.", a:"Art. 277 CP", f:"Texto legal"}
];
